esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function taking an input amount to withdraw and a prior deposit amount to set up state.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "not enough balance to fund deposit");
        // Ensure depositAmount is positive to make the setup meaningful
        require(depositAmount > 0, "depositAmount must be > 0");

        // 1) Deposit depositAmount into c from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Read observable state before withdraw
        uint256 beforeContractBalance = address(c).balance;
        // There is no public getter for balances mapping (it's private in P), but the contract does not expose it.
        // However, we can still observe the contract's ETH balance and this contract's ETH balance.
        uint256 beforeSelfBalance = address(this).balance;

        // Try to withdraw withdrawAmount and capture whether it reverted
        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read observable state after withdraw
        uint256 afterContractBalance = address(c).balance;
        uint256 afterSelfBalance = address(this).balance;

        // General rule: If withdraw did not revert then:
        //  - The test contract's ETH balance increased by exactly withdrawAmount
        //  - The contract's ETH balance decreased by exactly withdrawAmount
        // If withdraw reverted then balances do not change (contract and self remain unchanged).
        assert(reverted
            ? (afterContractBalance == beforeContractBalance && afterSelfBalance == beforeSelfBalance)
            : (afterSelfBalance == beforeSelfBalance + withdrawAmount && beforeContractBalance == afterContractBalance + withdrawAmount)
        );
    }

    receive() external payable { }
}

